-function cherryPickAll( PRs ) {
-	let remainingPRs = [...PRs];
-	let i = 1;
-	let allSuccesses = [];
-	while ( remainingPRs.length ) {
-		console.log( `Cherry-picking round ${ i ++ }: ` );
-		const [successes, failures] = cherryPickRound( remainingPRs );
-		allSuccesses = [...allSuccesses, ...successes];
