+				} }
+			/>
+			<Elevation
+				borderRadius={ 9999 }
+				isInteractive={ false }
+				value={ 3 }
+			/>
+		</View>
+	);
+};
+
+const AnimatedAvatars = () => {
+	const props = {
+		offset: number( 'offset', 20 ),
+		isLayered: boolean( 'isLayered', true ),
+		isReversed: boolean( 'isReversed', false ),
+	};
