+	return (
+		<HStack>
+			<View>
+				<ZStack { ...props }>
+					<Avatar backgroundColor="#444" />
+					<Avatar backgroundColor="#777" />
+					<Avatar backgroundColor="#aaa" />
+					<Avatar backgroundColor="#fff" />
+				</ZStack>
+			</View>
+		</HStack>
+	);
+};
+
+export const _default = () => {
+	return (
+		<View>
+			<AnimatedAvatars />
+		</View>
+	);
+};

