+import PostTemplateActions from './actions';
+import { store as editPostStore } from '../../../store';
+
+/**
+ * Module Constants
+ */
+const PANEL_NAME = 'template';
+
+export function TemplatePanel() {
+	const {
+		isEnabled,
+		isOpened,
+		isPostsPage,
+		selectedTemplate,
+		availableTemplates,
+		fetchedTemplates,
+		isViewable,
+		template,
+		supportsTemplateMode,
+		canUserCreate,
+	} = useSelect( ( select ) => {
+		const {
+			isEditorPanelEnabled,
+			isEditorPanelOpened,
+			getEditedPostTemplate,
+		} = select( editPostStore );
+		const {
+			getEditedPostAttribute,
+			getEditorSettings,
+			getCurrentPostId,
+			getCurrentPostType,
+		} = select( editorStore );
+		const {
+			getPostType,
+			getEntityRecord,
+			getEntityRecords,
+			canUser,
+		} = select( coreStore );
+
+		const currentPostId = getCurrentPostId();
+		const currentPostType = getCurrentPostType();
+		const settings = getEntityRecord( 'root', 'site' );
+		const _isViewable = getPostType( currentPostType )?.viewable ?? false;
+		const _supportsTemplateMode =
+			select( editorStore ).getEditorSettings().supportsTemplateMode &&
+			_isViewable;
+
+		const templateRecords = getEntityRecords( 'postType', 'wp_template', {
+			post_type: currentPostType,
+			per_page: -1,
+		} );
+
+		return {
+			isEnabled: isEditorPanelEnabled( PANEL_NAME ),
+			isOpened: isEditorPanelOpened( PANEL_NAME ),
+			isPostsPage: currentPostId === settings?.page_for_posts,
